arguments.prompt:
You are implementing a Blazor Web App shipment tracker for a logistics company. The project has already been scaffolded at `/tmp/sv-9c23d7c5befc40bfbb94eba9a12ef23a/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

The project structure:
- `ShipmentTracker/` (server project) - hosts the app, has EF Core + Identity + SQLite
- `ShipmentTracker.Client/` (client project) - interactive components run here

Key rules for Auto Global mode:
- All interactive components MUST go in the `.Client` project
- No direct DB access from `.Client` - must use HttpClient to call server APIs
- Define service interfaces in `.Client`, implement with HttpClient there, implement with direct DB access on server
- Both Program.cs files must register matching services
- No `@rendermode` needed on pages (global mode)

## What to implement:

### 1. Shared Models (in `.Client` project since both sides need them)

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}
```

### 2. Service Interface (in `.Client` project)

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task<Shipment> UpdateShipmentAsync(Shipment shipment);
}
```

### 3. Client-side implementation (HttpClient-based, in `.Client` project)

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}
```

### 4. Server-side DB entity and DbContext update

Create `ShipmentTracker/Data/ShipmentEntity.cs`:
```csharp
namespace ShipmentTracker.Data;

public class ShipmentEntity
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public int Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<ShipmentEntity> Shipments => Set<ShipmentEntity>();
}
```

### 5. Server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.Select(e => ToModel(e)).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : ToModel(entity);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var entity = ToEntity(shipment);
        entity.TrackingNumber = GenerateTrackingNumber();
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return ToModel(entity);
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var entity = await db.Shipments.FindAsync(shipment.Id)
            ?? throw new InvalidOperationException("Shipment not found");
        entity.Origin = shipment.Origin;
        entity.Destination = shipment.Destination;
        entity.Status = (int)shipment.Status;
        entity.ShippedDate = shipment.ShippedDate;
        entity.EstimatedDelivery = shipment.EstimatedDelivery;
        entity.ActualDelivery = shipment.ActualDelivery;
        entity.CustomerEmail = shipment.CustomerEmail;
        entity.Description = shipment.Description;
        await db.SaveChangesAsync();
        return ToModel(entity);
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }

    private static Shipment ToModel(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = (ShipmentStatus)e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        ActualDelivery = e.ActualDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };

    private static ShipmentEntity ToEntity(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (int)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}
```

### 6. API Endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
namespace ShipmentTracker.Endpoints;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
        {
            var shipments = await service.GetAllShipmentsAsync();
            return Results.Ok(shipments);
        });

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).AllowAnonymous();

        group.MapPost("", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });

        group.MapPut("{id:int}", async (int id, Shipment shipment, IShipmentService service) =>
        {
            shipment.Id = id;
            var updated = await service.UpdateShipmentAsync(shipment);
            return Results.Ok(updated);
        });
    }
}
```

